int getScore(JNIEnv *env, jobject this) {
  jclass cls = env->FindClass("Snake");
  jfieldID fid = env->GetFieldID(cls, "score", "I");
  jint score = env->GetIntField(this, fid);
  return score;
}

void move(JNIEnv *env, jobject this, jint direction) {
  jclass cls = env->FindClass("Snake");
  jmethodID mid = env->GetMethodID(cls, "updatePosition", "(I)V");
  env->CallVoidMethod(this, mid, direction);
  return;
}

void reset(JNIEnv *env, jobject this) {
  jclass cls = env->FindClass("Board");
  jfieldID fid = env->GetFieldID(cls, "cells", "[[I");
  jint rows = 10;
  jint cols = 10;
  jobjectArray arr = env->NewObjectArray(rows, env->FindClass("[I"), 0);
  env->SetObjectField(this, fid, arr);
  return;
}
